entity User {
    roles: Set<Role>,
    reviewerLevel: Long,
};

entity Campaign {
    advertiser: User,
    preparedBy: User,
    budget: decimal,
    contingency: decimal,
    budgetTier: Long,
    riskLabels: Set<String>,
    scheduledStart: datetime,
    status: String,
};

entity Creative {
    campaign: Campaign,
    submittedBy: User,
    riskRating: Long,
    contentTags: Set<String>,
    status: String,
};

action approveCampaignBudget appliesTo {
    principal: [User],
    resource: [Campaign],
    context: {
