    roles: Set<Role>,
};

entity Application {
    applicant: User,
    assignedReviewers: Set<User>,
    fundingTier: String,
    requestedAmount: Long,
    programCode: String,
    status: String,
    crossesMoneyThreshold: Bool,
};

entity Award {
    application: Application,
    approvedBy: User,
    obligatedBy: User,
    amount: Long,
    highRisk: Bool,
    status: String,
};

action scoreApplication appliesTo {
    principal: [User],
    resource: [Application],
