    stateLicense: String,
};

entity Patient;

entity Prescription {
    prescriber: User,
    patient: Patient,
    enteredBy: User,
    verifiedBy: User,
    prescriberDeaIdentifier: String,
    scheduleLevel: String,
    refillsRemaining: Long,
    status: PrescriptionStatus,
};

entity DispenseRecord {
