    roles: Set<Role>,
};

entity Role enum ["recruiter", "hiringManager", "interviewer", "coordinator"];

entity HiringTeam;

entity Application {
    candidate: String,
    referrer: String,
    hiringTeam: HiringTeam,
    reqCode: String,
    piiSensitivity: String,
    status: String,
};

entity InterviewFeedback;

entity Offer {
    application: Application,
    extendedBy: User,
    compensation: decimal,
    signingBonus: decimal,
    status: String,
    approvalWindowStart: datetime,
    approvalWindowEnd: datetime,
};

action approveOffer appliesTo {
    principal: [User],
    resource: [Offer],
    context: {
        onCorporateNetwork: Bool,
        currentTime: datetime,
        executiveApprovalPresent: Bool,
    },
};
```

