    roles: Set<Role>,
    badgeClearanceLevel: Long,
    assignedZoneGroups: Set<ZoneGroup>,
};

entity ZoneGroup;

entity Zone {
    zoneCode: String,
    sensitivityLevel: Long,
    zoneGroup: ZoneGroup,
    isLocked: Bool,
    operationalStatus: String,
};

entity Order {
    requestedBy: Person,
    picker?: Person,
    items: Set<String>,
    itemCount: Long,
    pickListCode: String,
    status: String,
    destinationZone: Zone,
    releasedAt?: datetime,
};

action pickOrder appliesTo {
    principal: [Person],
    resource: [Order],
};

action accessDestinationZone appliesTo {
    principal: [Person],
    resource: [Zone],
    context: {
        order: Order,
    },
};
```

